(()=>{const $=id=>document.getElementById(id),n=id=>parseFloat($(id).value),fmt=v=>v.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});function go(){const initial=n('initial'),base=n('monthly'),rate=n('rate'),years=n('years'),step=n('step');if(![initial,base,rate,years,step].every(Number.isFinite)||initial<0||base<0||years<0||step<0||rate<=-100){$('note').textContent='Enter non-negative contributions and duration; annual return must be greater than -100%.';$('note').className='helper danger';return;}const months=Math.round(years*12),mr=Math.pow(1+rate/100,1/12)-1;let bal=initial,invested=initial,monthly=base;for(let m=1;m<=months;m++){if(m>1&&(m-1)%12===0)monthly*=1+step/100;if($('timing').value==='begin'){bal+=monthly;invested+=monthly;bal*=1+mr}else{bal*=1+mr;bal+=monthly;invested+=monthly}}$('fv').textContent=fmt(bal);$('invested').textContent=fmt(invested);$('gain').textContent=fmt(bal-invested);$('note').textContent='Projection assumes the same effective annual return is earned smoothly each month. Actual market returns, fees, taxes and cash-flow dates vary.';$('note').className='helper';}
